/// <summary>
/// Framework class for Data contract classes that utilise Queries.
/// MPJ_24248 Pricing Data Extract
/// </summary>
abstract class METSysOperationQueryDataContractBase
{
    str         encodedQuery;
    QueryName   queryName;
 
}

Method.Source:
/// <summary>Creates new query</summary>
/// <returns>New Query</returns>
public Query createQuery()
{
    Query query = new Query(this.queryName());
    return Query;
}

/// <summary>Parms the string query object</summary>
/// <param name = "_encodedQuery">The query</param>
/// <returns>Query as a string</returns>
public str parmEncodedQuery(str _encodedQuery = encodedQuery)
{
    encodedQuery = _encodedQuery;
    return encodedQuery;
}

/// <summary>Set the query object in this class</summary>
/// <param name = "_query">The query</param>
/// <returns>Query</returns>
public Query Query(Query _query = null)
{
    if(prmisDefault(_query))
    {
        return METSysOperationQueryDataContractBase::DataContractQuery(this);
    }
    return METSysOperationQueryDataContractBase::DataContractQuery(this, _query);
}

   /// <summary>Get the query name</summary>
   /// <returns>Query name</returns>
   public final str queryName()
   {
       if(queryName == '')
       {
           queryName = METSysOperationQueryDataContractBase::DataContractQueryName(this);
       }

       return queryName;
   }

    /// <summary>Set the query in this class</summary>
    /// <param name = "_dataContract">This class</param>
    /// <param name = "_query">The query</param>
    /// <returns>Query</returns>
    public static Query DataContractQuery(METSysOperationQueryDataContractBase _dataContract,  Query _query = null)
    {
        if(prmisDefault(_query) == false)
        {
            if(_query != null)
            {
                _dataContract.parmEncodedQuery(SysOperationHelper::base64Encode(_query.pack()));
            }
            else
            {
                _dataContract.parmEncodedQuery('');
            }
        }

        if(_dataContract.parmEncodedQuery() == '')
        {
            _dataContract.parmEncodedQuery(SysOperationHelper::base64Encode(_dataContract.createQuery().pack()));
        }
 
        return new Query(SysOperationHelper::base64Decode(_dataContract.parmEncodedQuery()));
    }

    /// <summary>Encodes the query object to a string</summary>
    /// <param name = "_dataContract">This class</param>
    /// <returns>query name</returns>
    public static queryName DataContractQueryName(METSysOperationQueryDataContractBase _dataContract)
    {
        DictMethod  dictMethod = new DictMethod(UtilElementType::ClassInstanceMethod, classIdGet(_dataContract), methodStr(METSysOperationQueryDataContractBase, parmEncodedQuery));
        
        AifQueryTypeAttribute  aifQueryTypeAttribute = dictMethod.getAttribute(classStr(AifQueryTypeAttribute));

        queryName queryName = '';

        if(aifQueryTypeAttribute != null)
        {
            queryName = aifQueryTypeAttribute.queryName();
        }
 
        return queryName;
    }
